function dataList(api: any, bucket: keyof typeof seed): any[] {
  const remote = Array.isArray(api) ? api : [];
  return remote.length ? remote : (seed[bucket] || []);
}
function localized(item: any, key: string, lang: Lang, fallback='') { return val(item?.data, key, lang, fallback); }

function App() {
  const [lang,setLang] = useState<Lang>(() => (localStorage.getItem('rcy-lang') as Lang) || 'bn');
  useEffect(()=>{localStorage.setItem('rcy-lang',lang);document.documentElement.lang=lang;},[lang]);
  const toggle=()=>setLang(v=>v==='bn'?'en':'bn');
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><RouteRenderer lang={lang} toggle={toggle}/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;
}
function RouteRenderer({lang,toggle}:{lang:Lang;toggle:()=>void}) {
  const [path]=useLocation();
  const adminPath=path.replace(/^\/admin(?=\/|$)/i,'/admin').replace(/\/+$/,'')||'/';
  const adminKey=adminPath.toLowerCase();
  const isAdmin=/^\/admin(?:\/|$)/i.test(path);
  const isApplicationDetail=/^\/admin\/applications\/[^/]+$/i.test(adminPath);
  const knownAdminPath=['/admin','/admin/applications','/admin/settings','/admin/content','/admin/inbox','/admin/users'].includes(adminKey)||isApplicationDetail;
  const adminPage=adminKey==='/admin/login'
    ? <Login lang={lang} toggle={toggle}/>
    : knownAdminPath ? <Admin lang={lang} toggle={toggle}/> : <NotFound/>;
  return <ErrorBoundary resetKey={path}>{isAdmin?adminPage:<PublicShell lang={lang} toggle={toggle}><Switch>
    <Route path="/" component={()=><Home lang={lang}/>} />
    <Route path="/about" component={()=><About lang={lang}/>} />
    <Route path="/programs" component={()=><Listing lang={lang} collection="programs" title={bilingual('আমাদের কার্যক্রম','Our programs')}/>} />
    <Route path="/programs/:slug" component={()=><PublicItem lang={lang} collection="programs"/>}/>
    <Route path="/people" component={()=><People lang={lang}/>} />
    <Route path="/news" component={()=><Listing lang={lang} collection="news" title={bilingual('ইউনিটের খবর','From the unit')}/>} />
    <Route path="/news/:slug" component={()=><PublicItem lang={lang} collection="news"/>}/>
    <Route path="/events" component={()=><Listing lang={lang} collection="events" title={bilingual('আসন্ন আয়োজন','Upcoming events')}/>} />
    <Route path="/gallery" component={()=><Gallery lang={lang}/>} />
    <Route path="/notices" component={()=><Listing lang={lang} collection="notices" title={bilingual('নোটিশ বোর্ড','Notice board')}/>} />
    <Route path="/faq" component={()=><Faq lang={lang}/>} />
    <Route path="/contact" component={()=><Contact lang={lang}/>} />
    <Route path="/join" component={()=><Join lang={lang}/>} />
    <Route path="/application-status" component={()=><ApplicationStatusPage lang={lang}/>} />
    <Route component={NotFound}/>
  </Switch></PublicShell>}</ErrorBoundary>;
}

