 const setView=goToView;
  const label=(v:AdminView):string=>({overview:copy(lang,'ওভারভিউ','Overview'),settings:copy(lang,'সাইট সেটিংস','Site settings'),applications:copy(lang,'সদস্য আবেদন','Applications'),inbox:copy(lang,'বার্তা ইনবক্স','Contact inbox'),content:copy(lang,'কনটেন্ট ম্যানেজার','Content manager'),users:copy(lang,'অ্যাডমিন অ্যাকাউন্ট','Admin accounts')}[v]);
  const navItems:AdminView[]=['overview','settings','content','applications','inbox'];
  if(user.role==='super_admin')navItems.push('users');
 return <div className="min-h-[100dvh] bg-[#faf6f4] text-[#30131a]"><header className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b border-rose-100 bg-white/95 px-4 backdrop-blur sm:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMobileNav(!mobileNav)} className="rounded-lg p-2 text-[#8F0A1F] lg:hidden" aria-label={copy(lang,'মেনু','Menu')} data-testid="admin-mobile-menu"><Menu size={20}/></button><img src="/assets/bdrcs-logo.png" alt={copy(lang,'বিডিআরসিএস লোগো','BDRCS emblem')} className="h-9 w-9 rounded-full"/><div><div className="text-sm font-extrabold text-[#8F0A1F]">{copy(lang,'RCY ইউনিট ডেস্ক','RCY Unit Desk')}</div><div className="hidden text-[10px] text-stone-500 sm:block">Chatkhil · Noakhali</div></div></div><div className="flex items-center gap-2 sm:gap-3"><button onClick={toggle} className="rounded-full border border-rose-200 px-3 py-2 text-[11px] font-bold text-[#8F0A1F]" data-testid="admin-language-toggle">{lang==='bn'?'EN':'বাংলা'}</button><span className="hidden text-xs text-stone-500 sm:block">{user.email}</span><Link href="/" className="hidden text-xs font-bold text-stone-600 no-underline sm:block" data-testid="admin-public-site">{copy(lang,'পাবলিক সাইট','Public site')} ↗</Link><button onClick={logoutNow} className="inline-flex items-center gap-2 rounded-full border border-rose-200 px-3 py-2 text-xs font-bold text-[#8F0A1F]" data-testid="button-admin-logout"><LogOut size={14}/><span className="hidden sm:inline">{copy(lang,'বের হন','Sign out')}</span></button></div></header>
  <div className="mx-auto flex max-w-[1500px]"><aside className={`${mobileNav?'block':'hidden'} fixed inset-y-[68px] left-0 z-20 w-[270px] border-r border-rose-100 bg-[#fffafa] p-4 lg:sticky lg:top-[68px] lg:block lg:h-[calc(100dvh-68px)] lg:shrink-0`}><div className="eyebrow mb-4 mt-2 px-3">{copy(lang,'ইউনিট পরিচালনা','UNIT MANAGEMENT')}</div>{navItems.map((v,i)=>{const icons=[LayoutDashboard,Settings,FileText,ClipboardList,Inbox,Users];const Icon=icons[i];return <button key={v} onClick={()=>goToView(v)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${view===v?'bg-[#8F0A1F] text-white':'text-stone-600 hover:bg-rose-50'}`} data-testid={`admin-nav-${v}`}><Icon size={17}/>{label(v)}{v==='inbox'&&<span className="ml-auto h-2 w-2 rounded-full bg-[#C8102E]"/>}</button>})}<div className="mt-8 rounded-2xl bg-[#fff1f2] p-4"><div className="text-xs font-bold text-[#8F0A1F]">{copy(lang,'দ্রুত প্রকাশ','Quick links')}</div><Link href="/join" className="mt-3 block text-xs text-stone-600 no-underline" data-testid="admin-preview-join">{copy(lang,'আবেদন ফর্ম দেখুন','Preview application form')} ↗</Link><Link href="/application-status" className="mt-2 block text-xs text-stone-600 no-underline" data-testid="admin-preview-status">{copy(lang,'স্ট্যাটাস পেজ দেখুন','Preview status page')} ↗</Link></div></aside><main className="min-w-0 flex-1 p-4 sm:p-7 lg:p-9">{view==='overview'?<AdminOverview lang={lang} setView={setView}/>:view==='settings'?<AdminSettings lang={lang}/>:view==='applications'?<AdminApplications lang={lang} applicationId={applicationId}/>:view==='inbox'?<AdminInbox lang={lang}/>:view==='users'?user.role==='super_admin'?<AdminUsersPage lang={lang} currentEmail={user.email}/>:<section className="rounded-2xl border border-rose-100 bg-white p-7" role="alert"><h1 className="text-xl font-extrabold text-[#8F0A1F]">{copy(lang,'এই অংশটি শুধু Super Admin-দের জন্য','Super Admin access required')}</h1><p className="mt-2 text-sm text-stone-600">{copy(lang,'অ্যাডমিন অ্যাকাউন্ট পরিচালনার অনুমতি আপনার নেই।','You do not have permission to manage admin accounts.')}</p></section>:<AdminContent lang={lang} collection={collection} setCollection={setCollection}/>}</main></div></div>;
