 return <><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">{copy(lang,'এক নজরে','AT A GLANCE')}</div><h1 className="display mt-2 text-3xl font-extrabold sm:text-4xl">{copy(lang,'ইউনিট ডেস্ক','Unit desk')}</h1><p className="mt-2 text-sm text-stone-500">{copy(lang,'আজকের কাজ, দ্রুত দেখা।','A quick look at the work today.')}</p></div><div className="font-mono text-xs text-stone-500">{new Date().toLocaleDateString(lang==='bn'?'bn-BD':'en-BD',{dateStyle:'long'})}</div></div>
 {error&&<div className="mt-5"><ErrorState lang={lang} onRetry={()=>refetch()}/></div>}
 {isLoading?<div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div className="h-32 animate-pulse rounded-2xl bg-rose-100"/><div className="h-32 animate-pulse rounded-2xl bg-rose-100"/><div className="h-32 animate-pulse rounded-2xl bg-rose-100"/><div className="h-32 animate-pulse rounded-2xl bg-rose-100"/></div>:<><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[[copy(lang,'অপেক্ষমাণ আবেদন','Pending applications'),overview?.applications?.pending??0,ClipboardList], [copy(lang,'অনুমোদিত','Approved'),overview?.applications?.approved??0,Check], [copy(lang,'প্রত্যাখ্যাত','Declined'),overview?.applications?.rejected??0,X],[copy(lang,'অপঠিত বার্তা','Unread messages'),overview?.unreadMessages??0,MessageCircle]].map(([name,n,I]:any,i:number)=><button key={i} onClick={()=>setView(i===3?'inbox':'applications')} className="rounded-2xl border border-rose-100 bg-white p-5 text-left transition hover:-translate-y-1 hover:shadow-md" data-testid={`overview-metric-${i}`}><div className="flex items-center justify-between text-xs font-semibold text-stone-500">{name}<I size={18} className="text-[#C8102E]"/></div><div className="display mt-4 text-4xl font-extrabold text-[#30131a]">{n}</div></button>)}</div><div className="mt-7 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl border border-rose-100 bg-white p-6"><div className="flex items-center justify-between"><h2 className="font-extrabold">{copy(lang,'সাম্প্রতিক কার্যক্রম','Recent activity')}</h2><button onClick={()=>setView('applications')} className="text-xs font-bold text-[#C8102E]" data-testid="button-open-applications">{copy(lang,'আবেদন দেখুন','View applications')} →</button></div>{overview?.recentActivity?.length?<div className="mt-4 divide-y divide-rose-50">{overview.recentActivity.slice(0,6).map((a:any,i:number)=><div key={i} className="flex items-center gap-3 py-3 text-sm"><span className="h-2 w-2 rounded-full bg-[#C8102E]"/><span className="text-stone-600">{String(a.message||a.action||a.title||copy(lang,'নতুন কার্যক্রম','Recent activity'))}</span></div>)}</div>:<div className="mt-4"><EmptyState lang={lang}/></div>}</div><div className="rounded-2xl bg-[#8F0A1F] p-6 text-white"><div className="eyebrow !text-rose-200">{copy(lang,'কনটেন্ট স্টুডিও','CONTENT STUDIO')}</div><h2 className="display mt-3 text-2xl font-extrabold">{copy(lang,'নতুন খবর বা কার্যক্রম প্রকাশ করুন।','Publish a story or a program.')}</h2><p className="mt-2 text-sm leading-6 text-rose-100/80">{copy(lang,'দ্বিভাষিক কনটেন্ট তৈরি ও সম্পাদনা করতে CMS খুলুন।','Open the CMS to create and edit bilingual content.')}</p><button onClick={()=>setView('content')} className="mt-5 rounded-full bg-white px-4 py-2.5 text-sm font-bold text-[#8F0A1F]" data-testid="button-open-cms">{copy(lang,'কনটেন্ট ম্যানেজার','Open content manager')} <ArrowRight size={14} className="ml-1 inline"/></button></div></div></>}</>;
