const csvCols:[string,string][]=[['applicationId','Application ID'],['status','Status'],['submittedAt','Submitted'],['academicYear','Academic year'],['name','Name'],['rollNo','Roll'],['branch','Branch'],['motherName','Mother'],['fatherName','Father'],['p_village','Permanent village'],['p_houseName','Permanent house'],['p_postOffice','Permanent post office'],['p_upazila','Permanent upazila'],['p_district','Permanent district'],['c_village','Present village'],['c_houseName','Present house'],['c_postOffice','Present post office'],['c_upazila','Present upazila'],['c_district','Present district'],['nationality','Nationality'],['religion','Religion'],['guardianName','Guardian'],['guardianMobile','Guardian mobile'],['dateOfBirth','Date of birth'],['note','Admin note']];
function exportApplicationsCsv(rows:any[]){
  const q=(v:any)=>`"${String(v??'').replace(/"/g,'""')}"`;
  const flat=(r:any)=>{const d=r.data||{};const p=d.permanentAddress||{};const c=d.presentAddress||{};const o:any={...d,...r,p_village:p.village,p_houseName:p.houseName,p_postOffice:p.postOffice,p_upazila:p.upazila,p_district:p.district,c_village:c.village,c_houseName:c.houseName,c_postOffice:c.postOffice,c_upazila:c.upazila,c_district:c.district};return csvCols.map(([k])=>q(o[k])).join(',')};
  const text='\ufeff'+csvCols.map(([,h])=>q(h)).join(',')+'\r\n'+rows.map(flat).join('\r\n');
  const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`rcy-applications-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url);
}
